#!/usr/bin/env node
/**
 * Бюджет бандла (PERFORMANCE-v8 § 10.1, `PERF-BUDGET-CODE-VS-DATA`).
 * Запуск: після `npm run build`.
 *
 * **Що саме міряється — і чому не те, що в каноні.** Шаблон канону складає
 * `build/_app/immutable/entry`. У цьому проєкті там 2 КБ: Vite ділить збірку по
 * маршрутах, і в `entry` лежить лише завантажувач. Бюджет над цією текою був би
 * зеленим завжди й не значив би нічого — рівно те, від чого канон застерігає в
 * тому ж § 10.1 («якщо шлях зміниться, перевірка має ВПАСТИ, а не мовчки
 * знайти нуль файлів»).
 *
 * Тому міряється КРИТИЧНИЙ ШЛЯХ: усе, що `build/index.html` просить
 * передзавантажити. Це те, що справді доїжджає до браузера, перш ніж людина
 * побачить першу картку, і те, що зростає непомітно — від одного статичного
 * імпорту в кореневому шарі. Той самий перелік уже читає `check-build.mjs` для
 * перевірки, що SDK бази поза критичним шляхом.
 *
 * ## Два числа, а не одне: код окремо, реєстр окремо
 *
 * Доти стеля була одна на все, і це робило її гейтом на ЗМІСТ, а не на код.
 * У критичному шляху лежить таблиця `import.meta.glob` — 950 записів виду
 * `"./translations/uk/levels/A1_basic.json": () => import(…)`. Це не логіка, а
 * адреси контенту: додана мова чи новий файл рівня дописують туди рядки, не
 * додавши жодного оператора. Заміряно 2026-09-02: 70 КБ сирого тексту, 12 КБ
 * gzip — і всі 12 сиділи в тому самому числі, що й код. Восьма мова зробила б
 * бюджет червоним, а причина читалася б як «код погладшав».
 *
 * Тому тепер рахуються ДВА числа:
 *
 *   * `LIMIT_CODE_KB` — критичний шлях БЕЗ записів реєстру. Саме він і є
 *     бюджетом коду;
 *   * `LIMIT_DATA_KB` — скільки в критичному шляху коштує сам реєстр адрес.
 *
 * Запас у кожного той самий, що був у спільної стелі (20 КБ): 240 − 220 до
 * поділу, 228 − 208 і 20 − 12 після. Тобто поділ нічого не послабив і нічого
 * не посилив — він лише розвів дві причини зростання, які доти були одним
 * числом. Обидві стелі можуть лише ЗНИЖУВАТИСЯ, як поріг axe
 * (A11Y-AXE-BASELINE).
 *
 * Орієнтир канону — 150 КБ; названий тут, щоб не забувався.
 *
 * **Канарка на маркер реєстру.** Нуль знайдених записів означає не «реєстр
 * схуднув», а «форма запису змінилася» — і тоді 12 КБ мовчки переїжджають у
 * число коду, а перевірка стає мертвою (AI-AGENT-PITFALLS-v8 § 1). Тому нуль
 * валить прогін.
 *
 * Зворотний експеримент (AI-AGENT-PITFALLS-v8 § 1.1): знизити `LIMIT_CODE_KB`
 * до поточного розміру мінус один — скрипт мусить упасти й назвати обидва
 * числа.
 */
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { gzipSync } from 'node:zlib';

const BUILD = 'build';
const ENTRY = join(BUILD, 'index.html');

/** Стеля КОДУ в критичному шляху, КБ gzip. Заміряно 2026-09-02: 208. */
const LIMIT_CODE_KB = 228;

/** Стеля РЕЄСТРУ адрес контенту там само, КБ gzip. Заміряно 2026-09-02: 12. */
const LIMIT_DATA_KB = 20;

/**
 * Записи таблиці `import.meta.glob` — «адреса контенту → ліниве завантаження».
 *
 * Теки перелічені поіменно, а не `[^"]+`: інакше під правило потрапили б і
 * ліниві імпорти КОДУ (сервіси, компоненти), і бюджет коду почав би худнути
 * від того, що код винесли в дочірній чанк.
 */
const REGISTRY_ENTRY =
	/"\.\/(?:translations|transcriptions|phrases|words)\/[^"]+\.json":\(\)=>[^,}]+/g;

if (!existsSync(ENTRY)) {
	console.error(`${ENTRY} немає — спершу \`npm run build\`.`);
	process.exit(1);
}

const html = readFileSync(ENTRY, 'utf8');
const preloaded = [
	...new Set([...html.matchAll(/immutable\/(?:chunks|entry|nodes)\/[\w.-]+\.js/g)].map((m) => m[0]))
];

// Канарка: нуль файлів означає, що структура `build/` змінилася, а не що бандл
// схуднув до нічого. Без цього рядка перевірка ставала б зеленою саме тоді,
// коли перестала працювати.
if (preloaded.length === 0) {
	console.error(
		'index.html: жодного modulepreload — міряти нічого. Структура build/ змінилася?'
	);
	process.exit(1);
}

let totalBytes = 0;
let codeBytes = 0;
let registryEntries = 0;
const missing = [];
for (const rel of preloaded) {
	const file = join(BUILD, '_app', rel);
	if (!existsSync(file)) {
		missing.push(rel);
		continue;
	}
	const source = readFileSync(file, 'utf8');
	totalBytes += gzipSync(Buffer.from(source)).length;
	registryEntries += [...source.matchAll(REGISTRY_ENTRY)].length;
	// Різниця, а не сума довжин: gzip не адитивний, тож ціна реєстру — це
	// стільки, на скільки без нього худне вже стиснений файл.
	codeBytes += gzipSync(Buffer.from(source.replace(REGISTRY_ENTRY, ''))).length;
}

// Передзавантажений файл, якого немає на диску, — це 404 у критичному шляху.
if (missing.length > 0) {
	console.error(`index.html просить файли, яких у build/ немає:\n  • ${missing.join('\n  • ')}`);
	process.exit(1);
}

if (registryEntries === 0) {
	console.error(
		'у критичному шляху немає жодного запису реєстру контенту — форма запису ' +
			'`import.meta.glob` змінилася, і ціна реєстру мовчки переїхала в число коду'
	);
	process.exit(1);
}

const codeKb = Math.round(codeBytes / 1024);
const dataKb = Math.round((totalBytes - codeBytes) / 1024);
console.log(
	`Критичний шлях: ${Math.round(totalBytes / 1024)} КБ gzip у ${preloaded.length} файлах — ` +
		`код ${codeKb} (стеля ${LIMIT_CODE_KB}), реєстр адрес ${dataKb} ` +
		`у ${registryEntries} записах (стеля ${LIMIT_DATA_KB}).`
);

/**
 * ДОПУСК, а не точна рівність (CI-CD-AND-TOOLS-v9 § 1.18.1).
 *
 * Гейт порівнює ЗМІРЯНЕ число з порогом, а вимір залежить від машини. Заміряно
 * в `teatralo4ka` 2026-09-16: деплой упав на «758 КБ > 758», тоді як локальна
 * збірка ТОГО САМОГО дерева дала 757.78 — кількасот байтів різниці між
 * раннерами, тобто більше за типовий запас. Без допуску такий збіг червонить
 * прогін без жодної зміни в коді.
 *
 * Кілобайт перекриває розкид і НЕ перекриває справжній приріст: реальна правка
 * важить кілобайти. Іменована стала навмисно — сховане в порівнянні число
 * читалося б як «поріг точний».
 */
const TOLERANCE_KB = 1;

const over = [];
if (codeKb > LIMIT_CODE_KB + TOLERANCE_KB) {
	over.push(`код: ${codeKb} КБ проти ${LIMIT_CODE_KB} (допуск ${TOLERANCE_KB})`);
}
if (dataKb > LIMIT_DATA_KB + TOLERANCE_KB) {
	over.push(
		`реєстр адрес: ${dataKb} КБ проти ${LIMIT_DATA_KB} (допуск ${TOLERANCE_KB}) — ` +
			'це зростання від ДОДАНОГО КОНТЕНТУ, а не від доданого коду'
	);
}
if (over.length > 0) {
	console.error(
		`Бюджет перевищено: ${over.join('; ')}. Стеля може лише знижуватися — ` +
			'підіймати її замість того, щоб розібратися, означає скасувати сам бюджет.'
	);

	/**
	 * БЮДЖЕТ ЗВІТУЄ, АЛЕ НЕ ЗУПИНЯЄ ВИПУСК (CI-CD-AND-TOOLS-v9 § 1.18).
	 *
	 * `BUDGET_SOFT=1` ставить рівно одне місце — крок збірки в `deploy.yml`.
	 * Причина не в тому, що бюджет менш важливий, а в тому, ЩО САМЕ він
	 * перериває: деплой возить виправлення тексту й дані, на які чекають люди.
	 * Бюджет розміру відповідає на «чи продукт не гладшає» — це тренд, а не
	 * питання цілості.
	 *
	 * Локально — теж лише звіт, і це не м'якість: перевищення посеред задачі
	 * уриває роботу й змушує розбиратися зі стелею замість того, що робили.
	 *
	 * ЖОРСТКО те саме число перевіряє `.github/workflows/budgets.yml` — окремий
	 * прогін на тому самому `push`, паралельно з деплоєм. Гейт, який після
	 * винесення ніде не падає, не винесений, а вимкнений.
	 */
	if (process.env.BUDGET_SOFT === '1' || process.env.CI !== 'true') {
		console.error(
			'\n  ⚠️  не зупиняємо: тут бюджет лише звітує, жорстко його перевіряє прогін «Budgets».'
		);
		process.exit(0);
	}

	process.exit(1);
}
